#!/usr/bin/env python3
"""Generate module/payload_js.h from payload/inject.js."""
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parent.parent
src = root / "payload" / "inject.js"
dst = root / "module" / "payload_js.h"

data = src.read_bytes()
lines = [
    "/* Generated by scripts/gen_payload_header.py. Do not edit. */",
    "#pragma once",
    "static const unsigned char ytps5_payload_js[] = {",
]
for i in range(0, len(data), 16):
    chunk = data[i:i + 16]
    lines.append("  " + ", ".join(f"0x{b:02x}" for b in chunk) + ",")
lines.append("};")
lines.append(f"static const unsigned int ytps5_payload_js_len = {len(data)};")
lines.append("")
dst.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {dst} ({len(data)} bytes)")
